import json
from typing import Any, Dict, Optional, Tuple, List

import jax
import jax.numpy as jnp
from jax import random as jr
import flax.linen as nn
import optax

# -----------------------------
# Minimal defaults to satisfy loader (unused by test())
# -----------------------------
class _NullNet(nn.Module):
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B = x.shape[0]
        z = x.reshape((B, -1))
        h = nn.Dense(16, kernel_init=nn.initializers.xavier_uniform())(z)
        h = nn.relu(h)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(h)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(h).squeeze(-1)
        return policy_logits, value, {"h": jnp.zeros((B,))}

def create_network(hparams: Dict[str, Any] = None):
    return _NullNet()

def create_optimizer(learning_rate: float = 4e-4):
    return optax.adam(learning_rate)

# -----------------------------
# PG backbone and head variants for probes
# -----------------------------
class BottleneckDilatedBlock(nn.Module):
    features: int
    bottleneck_ratio: float = 0.28
    dilation: int = 6
    @nn.compact
    def __call__(self, x):
        mid = max(1, int(self.features * self.bottleneck_ratio))
        y = nn.Conv(mid, (1,1), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x)
        y = nn.relu(y)
        y = nn.Conv(mid, (3,3), padding='SAME',
                    kernel_dilation=(self.dilation, self.dilation),
                    kernel_init=nn.initializers.xavier_uniform())(y)
        y = nn.relu(y)
        y = nn.Conv(self.features, (1,1), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(y)
        return nn.relu(x + y)

class ConvLSTMCellLN(nn.Module):
    features: int
    kernel_size: Tuple[int,int] = (3,3)
    @nn.compact
    def __call__(self, carry, x):
        h, c = carry  # (B,H,W,C)
        gates_lin = nn.Conv(4*self.features, self.kernel_size, padding='SAME',
                            kernel_init=nn.initializers.xavier_uniform())(
            jnp.concatenate([x, h], axis=-1))
        gates_ln = nn.LayerNorm(epsilon=1e-5)(gates_lin)
        i_lin, f_lin, g_lin, o_lin = jnp.split(gates_ln, 4, axis=-1)
        i = nn.sigmoid(i_lin); f = nn.sigmoid(f_lin); o = nn.sigmoid(o_lin); g = jnp.tanh(g_lin)
        c = f * c + i * g
        h = o * jnp.tanh(c)
        gates = {"i_lin": i_lin, "f_lin": f_lin, "g_lin": g_lin, "o_lin": o_lin}
        return (h, c), h, gates

class FeatureExtractor(nn.Module):
    cnn1: int = 32
    cnn2: int = 64
    convlstm: int = 64
    dilation: int = 6
    bottleneck_ratio: float = 0.28
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B = x.shape[0]
        x = nn.Conv(self.cnn1, (3,3), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x); x = nn.relu(x)
        x = BottleneckDilatedBlock(self.cnn1, self.bottleneck_ratio, self.dilation)(x)
        x = nn.Conv(self.cnn2, (3,3), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x); x = nn.relu(x)
        x = BottleneckDilatedBlock(self.cnn2, self.bottleneck_ratio, self.dilation)(x)
        if rnn_state is None:
            zeros = lambda: jnp.zeros((B, 8, 8, self.convlstm), dtype=x.dtype)
            rnn_state = {'h': zeros(), 'c': zeros()}
        if done is not None:
            m = (1.0 - done.reshape(B,1,1,1).astype(x.dtype))
            rnn_state = {'h': rnn_state['h'] * m, 'c': rnn_state['c'] * m}
        (h_new, c_new), h_out, gates = ConvLSTMCellLN(self.convlstm)((rnn_state['h'], rnn_state['c']), x)
        rnn_state = {'h': h_new, 'c': c_new}
        return h_out, gates, rnn_state

def _attn_pool(h_out):
    B,H,W,C = h_out.shape
    logits = nn.Conv(1, (1,1), padding='SAME',
                     kernel_init=nn.initializers.xavier_uniform())(h_out).reshape((B, H*W))
    weights = nn.softmax(logits, axis=-1).reshape((B, H*W, 1))
    tokens = h_out.reshape((B, H*W, C))
    attn_vec = (weights * tokens).sum(axis=1)   # (B,C)
    return attn_vec, weights  # (B,C), (B,64,1)

class DualHead_AttnGap(nn.Module):
    head_hidden: int = 64
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        feats = FeatureExtractor()(x, done, rnn_state)
        h_out, gates, rnn_state = feats
        attn_vec, attn_w = _attn_pool(h_out)
        gap_vec = h_out.mean(axis=(1,2))
        z = jnp.concatenate([attn_vec, gap_vec], axis=-1)   # (B, 2C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        ph = nn.Dense(self.head_hidden, kernel_init=nn.initializers.xavier_uniform())(shared); ph = nn.relu(ph)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(ph)
        vh = nn.Dense(self.head_hidden, kernel_init=nn.initializers.xavier_uniform())(shared); vh = nn.relu(vh)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(vh).squeeze(-1)
        aux = {"z": z, "attn": attn_w, "gates": gates}
        return policy_logits, value, rnn_state, aux

class SimpleHead_Attn(nn.Module):
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        h_out, gates, rnn_state = FeatureExtractor()(x, done, rnn_state)
        attn_vec, attn_w = _attn_pool(h_out)
        z = attn_vec
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(shared)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(shared).squeeze(-1)
        aux = {"z": z, "attn": attn_w, "gates": gates}
        return policy_logits, value, rnn_state, aux

class GapOnly_Head(nn.Module):
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        h_out, gates, rnn_state = FeatureExtractor()(x, done, rnn_state)
        z = h_out.mean(axis=(1,2))
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(shared)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(shared).squeeze(-1)
        aux = {"z": z, "attn": None, "gates": gates}
        return policy_logits, value, rnn_state, aux

# -----------------------------
# Synthetic batch + metrics
# -----------------------------
def generate_synth(key, B=32):
    k1, k2, k3 = jr.split(key, 3)
    # one-hot categorical for channels 0..6 with 10% noise
    labels = jr.randint(k1, (B, 8, 8), 0, 7)
    oh = jax.nn.one_hot(labels, 7)  # (B,8,8,7)
    noise_mask = jr.bernoulli(k2, 0.10, (B,8,8,1))
    noise_lbl = jr.randint(k3, (B,8,8), 0, 7)
    noise_oh = jax.nn.one_hot(noise_lbl, 7)
    ch07 = jnp.where(noise_mask>0.5, noise_oh, oh)
    # time channel
    kt = jr.fold_in(key, 123)
    time_ch = jr.uniform(kt, (B,8,8,1))
    x = jnp.concatenate([ch07, time_ch], axis=-1)  # (B,8,8,8)
    done = jnp.zeros((B,), dtype=jnp.float32)
    return x, done

def attn_entropy_and_topk(w: jnp.ndarray, k=5):
    # w: (B,64,1)
    if w is None:
        return None
    w = w.squeeze(-1)
    eps = 1e-8
    H = -jnp.sum(w * jnp.log(jnp.clip(w, eps, 1.0)), axis=1)  # (B,)
    topk = jnp.sort(w, axis=1)[:, -k:]
    topk_mass = jnp.sum(topk, axis=1)  # (B,)
    return {
        "entropy_mean": float(jnp.mean(H)),
        "entropy_std": float(jnp.std(H)),
        "top5_mass_mean": float(jnp.mean(topk_mass)),
    }

def spectral_norm_dense(params: Dict[str, Any], iters=10):
    specs: List[float] = []
    # traverse params tree; collect 2D kernels (Dense layers)
    def _collect(tree, path=()):
        nonlocal specs
        if isinstance(tree, dict):
            for k,v in tree.items():
                _collect(v, path+(k,))
        else:
            # leaf
            pass
    # simple flatten
    def _flatten(d):
        for k,v in d.items():
            if isinstance(v, dict):
                yield from _flatten(v)
            else:
                # expecting v to be arrays only at 'kernel' or 'bias'
                pass
    # We manually walk to find 'kernel' arrays (common Flax naming)
    def _walk(d):
        for k,v in d.items():
            if isinstance(v, dict):
                if 'kernel' in v and isinstance(v['kernel'], jnp.ndarray):
                    W = v['kernel']
                    if W.ndim == 2:
                        specs.append(float(_power_iter(W, iters)))
                # recurse
                _walk(v)
    _walk(params)
    if not specs:
        return {"dense_spec_max": None, "dense_spec_mean": None}
    return {"dense_spec_max": float(jnp.max(jnp.array(specs))),
            "dense_spec_mean": float(jnp.mean(jnp.array(specs)))}

def _power_iter(W, iters=10):
    # W: (in, out)
    v = jnp.ones((W.shape[1],), dtype=W.dtype)
    v = v / (jnp.linalg.norm(v) + 1e-8)
    for _ in range(iters):
        v = W.T @ (W @ v)
        v = v / (jnp.linalg.norm(v) + 1e-8)
    sigma = jnp.linalg.norm(W @ v)
    return sigma

def gate_stats(gates: Dict[str, jnp.ndarray]):
    def _sat_sig(x):
        p = jax.nn.sigmoid(x)
        sat_low = jnp.mean((p < 0.05).astype(jnp.float32))
        sat_high = jnp.mean((p > 0.95).astype(jnp.float32))
        return sat_low, sat_high
    def _sat_tanh(x):
        t = jnp.tanh(x)
        sat = jnp.mean((jnp.abs(t) > 0.9).astype(jnp.float32))
        return sat
    out = {}
    for name in ["i_lin","f_lin","o_lin","g_lin"]:
        x = gates[name]
        if name == "g_lin":
            sat = _sat_tanh(x)
            out["g"] = {"mean": float(jnp.mean(x)), "std": float(jnp.std(x)),
                        "sat": float(sat)}
        else:
            lo, hi = _sat_sig(x)
            out[name[0]] = {"mean": float(jnp.mean(x)), "std": float(jnp.std(x)),
                            "sat_low": float(lo), "sat_high": float(hi)}
    return out

def grad_input_norm(model, variables, x, done):
    def f(inp):
        logits, _, _, _ = model.apply(variables, inp, done, None)
        return jnp.sum(logits)
    g = jax.grad(f)(x)  # same shape as x
    # per-sample L2 norms
    g_norm = jnp.sqrt(jnp.sum(g*g, axis=(1,2,3)))
    return float(jnp.mean(g_norm))

def run_one(model, key):
    B = 32
    x, done = generate_synth(key, B=B)
    variables = model.init(jr.fold_in(key, 0), x, done, None)
    logits, value, rnn_state, aux = model.apply(variables, x, done, None)
    # attention stats
    attn_stats = attn_entropy_and_topk(aux.get("attn", None))
    # spectral norms across Dense layers only
    specs = spectral_norm_dense(variables.get("params", {}), iters=10)
    # gate stats
    gstats = gate_stats(aux["gates"])
    # gradient amplification proxy (input gradient norm)
    gin = grad_input_norm(model, variables, x, done)
    result = {
        "attn": attn_stats if attn_stats is not None else "n/a",
        "dense_spectral_norm": specs,
        "gate_stats": gstats,
        "grad_input_l2_mean": float(gin),
    }
    return result

# -----------------------------
# test(): builds three heads, runs probes, prints JSON
# -----------------------------
def test():
    key = jr.PRNGKey(42)
    dual = DualHead_AttnGap(head_hidden=64)
    simple = SimpleHead_Attn()
    gap = GapOnly_Head()
    out = {
        "seed": 42,
        "batch": [32,8,8,8],
        "models": {
            "dual_attn_gap_deep": run_one(dual, jr.fold_in(key, 1)),
            "simple_head_attn": run_one(simple, jr.fold_in(key, 2)),
            "gap_only_head": run_one(gap, jr.fold_in(key, 3)),
        }
    }
    print(json.dumps(out, indent=2))
    return "OK"
